  "content.c1": "সহজলভ্যতার পরিচিতি",
  "content.c1d": "WCAG নির্দেশিকা, সহায়ক প্রযুক্তি এবং অন্তর্ভুক্তিমূলক নকশার মূলনীতিগুলো কভার করে এমন একটি সম্পূর্ণ কোর্স।",
