  "jungle.s8c1": "ধোঁয়ার দিকে যান — হতে পারে উদ্ধার! (+15 HP, +45 পয়েন্ট)",
  "jungle.s8c2": "এড়িয়ে চলুন — হতে পারে দাবানল (−5 HP, +15 পয়েন্ট)",
  "jungle.scene9": "রাত নেমে আসে। আপনার আশ্রয় দরকার।",
  "jungle.s9c1": "শিকারিদের থেকে নিরাপদ থাকতে উঁচু গাছে উঠুন (+10 HP, +30 পয়েন্ট)",
  "jungle.s9c2": "ডালপালা দিয়ে মাটির নিচু আশ্রয় বানান (−5 HP, +35 পয়েন্ট)",
  "jungle.scene10": "আপনি এমন একটি ফল খুঁজে পান যা আপনি চিনতে পারেন না। আপনি খুব ক্ষুধার্ত।",
  "jungle.s10c1": "খেয়ে ফেলুন — আপনি তো মরিয়া! (−20 HP, +30 পয়েন্ট)",
  "jungle.s10c2": "আগে ত্বকে এক টুকরো করে পরীক্ষা করুন (0 HP, +20 পয়েন্ট)",
  "jungle.scene11": "পথে একটি বড় সাপ কুণ্ডলী পাকিয়ে আছে।",
  "jungle.s11c1": "ধীরে ধীরে পেছান এবং বিকল্প পথ খুঁজুন (+5 HP, +30 পয়েন্ট)",
  "jungle.s11c2": "ওকে ভয় দেখিয়ে দূরে সরানোর চেষ্টা করুন (−25 HP, +40 পয়েন্ট)",
  "jungle.scene12": "আপনি একটা জলপ্রপাতের শব্দ শুনতে পান — আপনার পানি সরবরাহ খুবই কম।",
  "jungle.s12c1": "সেই শব্দ অনুসরণ করুন নতুন পানি খুঁজতে (+20 HP, +35 পয়েন্ট)",
  "jungle.s12c2": "এড়িয়ে গিয়ে সামনে এগোতে থাকুন (−15 HP, +20 পয়েন্ট)",
  "jungle.scene13": "ঝড় দ্রুত এগিয়ে আসছে।",
  "jungle.s13c1": "উঁচু জায়গা খুঁজে আড়াল নিন (+10 HP, +25 পয়েন্ট)",
  "jungle.s13c2": "এ থেকে পালাতে এগিয়ে যান (−10 HP, +30 পয়েন্ট)",
  "jungle.scene14": "আপনি একটি গুহা খুঁজে পান। অন্ধকার হচ্ছে।",
  "jungle.s14c1": "আশ্রয়ের জন্য গুহার ভেতর ঢুকুন (+15 HP, +30 পয়েন্ট)",
  "jungle.s14c2": "গাছের নিচে ঘুমান — গুহাটি হয়তো দখল করা আছে (+5 HP, +20 পয়েন্ট)",
  "jungle.scene15": "আপনি ক্লান্ত। সামনে একটি খোলা জায়গা নিরাপদ মনে হচ্ছে।",
  "jungle.s15c1": "বিশ্রাম নিন ও সুস্থ হয়ে উঠুন (+20 HP, +20 পয়েন্ট)",
  "jungle.s15c2": "চালিয়ে যান — এখানে বিশ্রাম নেওয়া বিপজ্জনক (−5 HP, +30 পয়েন্ট)",
  "jungle.scene16": "আপনি একটি গাছে খোদাই করা পুরোনো মানচিত্র খুঁজে পান।",
  "jungle.s16c1": "মানচিত্রের দিক অনুসরণ করুন (+5 HP, +40 পয়েন্ট)",
  "jungle.s16c2": "এড়িয়ে যান — এটা হয়তো পুরোনো (0 HP, +10 পয়েন্ট)",
  "jungle.scene17": "বন্য শূকররা আক্রমণাত্মকভাবে আপনার পথ অতিক্রম করে।",
  "jungle.s17c1": "সবচেয়ে কাছে যে গাছ আছে সেটাতে এখনই উঠুন (+5 HP, +30 পয়েন্ট)",
  "jungle.s17c2": "অবিচল থাকুন এবং চিৎকার করুন (−20 HP, +35 পয়েন্ট)",
  "jungle.scene18": "আপনি পরিত্যক্ত একটি ক্যাম্প খুঁজে পান, সেখানে সরবরাহ আছে।",
  "jungle.s18c1": "যা কাজে লাগবে সব নিন (+20 HP, +50 পয়েন্ট)",
  "jungle.s18c2": "এটা ছেড়ে দাও — পরে কারও লাগতে পারে (0 HP, +10 pts)",
  "jungle.scene19": "একটা বানর আপনার খাবারের ব্যাগ চুরি করে!",
  "jungle.s19c1": "বানরকে তাড়া করো (−10 HP, +40 pts)",
  "jungle.s19c2": "ছেড়ে দাও — এর জন্য এনার্জি খরচ করা ঠিক নয় (+0 HP, +15 pts)",
  "jungle.scene20": "তুমি মাথার উপর দিয়ে একটা হেলিকপ্টার শুনতে পাচ্ছো।",
  "jungle.s20c1": "এখনই সিগন্যাল ফায়ার জ্বালো! (+30 HP, +60 pts)",
  "jungle.s20c2": "হাত নেড়ে দাও — হয়তো তোমাকে দেখতে পাবে (+5 HP, +40 pts)",
