  "akinator.howTo.1": "কোনো বাস্তব বা কাল্পনিক চরিত্রের কথা ভাবো",
  "akinator.howTo.2": "প্রশ্নগুলোর উত্তর সৎভাবে দাও (Yes/Probably/Don't Know/Probably Not/No)",
  "akinator.howTo.3": "প্রতিটি উত্তরে AI সম্ভাব্যদের সংখ্যা কমিয়ে আনে",
  "akinator.howTo.4": "২০টি প্রশ্নের মধ্যে Akinator কি তোমার চরিত্রটা ধরতে পারে দেখো!",
  "neonbreach.howTo.1": "জ্বলতে থাকা নোডগুলোর সিকোয়েন্সটা মনোযোগ দিয়ে দেখো",
  "neonbreach.howTo.2": "তারপর ট্যাপ করে একই সিকোয়েন্সটা হুবহু আবার দাও",
  "neonbreach.howTo.3": "প্রতিটি সঠিক লেভেল মনে রাখার জন্য আরেকটি নোড যোগ করে",
  "neonbreach.howTo.4": "একবার ভুল ট্যাপ করলেই ফায়ারওয়াল তোমাকে ধরবে!",
  "earmaster.howTo.1": "যে মিউজিক নোট বাজছে সেটা মনোযোগ দিয়ে শোনো",
  "earmaster.howTo.2": "৭টি অপশনের মধ্যে তুমি যে নোটটা শুনেছ সেটা বেছে নাও",
  "earmaster.howTo.3": "নোটটা একবার আবার শুনতে Play বোতাম ব্যবহার করো",
  "earmaster.howTo.4": "চূড়ান্ত স্কোর দেখতে ১০টি রাউন্ড সম্পূর্ণ করো",
  "uno.howTo.1": "ডোমিনো চেইনের দুই প্রান্তের রং বা সংখ্যা মিলিয়ে কার্ডটা মেলাও",
  "uno.howTo.2": "খেলতে তোমার হাতে থাকা কোনো কার্ডে ট্যাপ করো",
  "uno.howTo.3": "ম্যাচ না থাকলে, কার্ড যোগ করতে Draw-এ ট্যাপ করো",
  "uno.howTo.4": "আগে যে নিজের হাত খালি করবে (First) সে জেতে!",
  "briscola.howTo.1": "Briscola হলো একটি ইতালীয় ট্রিক-টেকিং কার্ড গেম",
  "briscola.howTo.2": "ট্রাম্প স্যুট (Briscola) বাকি সব স্যুটকে হারায়",
  "briscola.howTo.3": "পয়েন্ট পেতে ট্রিক জেতো — Ace=11, 3=10, King=4, Queen=3, Jack=2",
  "briscola.howTo.4": "সব কার্ড খেলার পর সর্বোচ্চ স্কোর যে পাবে সে জেতে",
  "card99.howTo.1": "চলমান মোট ৯৯ বা তার নিচে রাখতে কার্ড খেলো",
  "card99.howTo.2": "বিশেষ কার্ড: King=0, Queen=hold, Jack=−10, Ace=1 বা 11",
  "card99.howTo.3": "মোট ৯৯-এর ওপরে পাঠিয়ে দাও—তাহলে একটি জীবন হারাবে",
  "card99.howTo.4": "শেষ পর্যন্ত যে খেলোয়াড়ের জীবন থাকবে সে জেতে!",
  "dominoes.howTo.1": "ডোমিনো চেইনের দুই প্রান্তে থাকা সংখ্যাগুলোর সাথে মিলাও",
  "dominoes.howTo.2": "ওপেন এন্ডের সাথে মেলে এমন টাইলগুলো হাতে থেকে খেলো",
  "dominoes.howTo.3": "খেলতে না পারলে পাইল থেকে ড্র করো",
  "dominoes.howTo.4": "যে আগে হাত খালি করবে (বা সর্বনিম্ন পিপ টোটাল) সে জেতে!",
  "farkle.howTo.1": "৬টা ডাইস ঘুরাও এবং স্কোরিং ডাইস যেগুলো আছে সেগুলো আলাদা করে রাখো",
  "farkle.howTo.2": "1s = 100 pts · 5s = 50 pts · Three-of-a-kind = face × 100",
  "farkle.howTo.3": "রোলের পর যদি কোনো ডাইস স্কোর না করে, তাহলে এটা হলো FARKLE — তোমার টার্ন শেষ!",
  "farkle.howTo.4": "পয়েন্টগুলো ব্যাংক করে রাখো যাতে সেগুলো থাকে, নাকি আরও ঝুঁকি/পুরস্কারের জন্য আবার রোল দাও",
  "quiz.howTo.1": "সম্ভব যত দ্রুত ২০টি মাল্টিপল-চয়েস প্রশ্নের উত্তর দাও",
  "quiz.howTo.2": "প্রতিটি প্রশ্নে ৩ সেকেন্ড — দ্রুত উত্তর দাও!",
  "quiz.howTo.3": "দ্রুত সঠিক উত্তর দিলে আরও বেশি বোনাস পয়েন্ট পাওয়া যায়",
  "quiz.howTo.4": "সব প্রশ্ন সম্পূর্ণ করো চূড়ান্ত র‌্যাঙ্ক দেখতে",
  "memory.howTo.1": "ম্যাচিং জোড়া খুঁজতে একবারে ২টি কার্ড উল্টাও",
  "memory.howTo.2": "মিলে গেলে সেগুলো মুখ উপরের দিকে থাকবে",
  "memory.howTo.3": "না মিললে দুটোই আবার মুখ নিচের দিকে উল্টে যাবে—মনে রাখো ওগুলো কোথায় ছিল!",
  "memory.howTo.4": "যত কম মুভে সম্ভব সব জোড়া মেলাও এবং বেশি স্কোর করো",
  "word.howTo.1": "জট পাকানো অক্ষরগুলো গুছিয়ে লুকানো শব্দ বানাও",
  "word.howTo.2": "উত্তর বানাতে সঠিক ক্রমে অক্ষরগুলোতে ট্যাপ করো",
  "word.howTo.3": "আটকে গেলে Hint বোতাম ব্যবহার করো (পয়েন্ট খরচ হয়)",
  "word.howTo.4": "পাজল শেষ করতে ৮টি শব্দ সম্পূর্ণ করো",
  "hangman.howTo.1": "একটি করে অক্ষর দিয়ে লুকানো শব্দটা অনুমান করো",
  "hangman.howTo.2": "সঠিক অক্ষর = শব্দের মধ্যে প্রকাশ পায়",
  "hangman.howTo.3": "ভুল অক্ষর = তোমার ৬টি সুযোগের মধ্যে ১টি শেষ হবে",
